    incoming = find(A(:,j));
    incoming(incoming == j) = [];

    targetBase = getBaseLabel(Gdir.Nodes.Name{j});

    validSources = [];

    for i = incoming'
        sourceBase = getBaseLabel(Gdir.Nodes.Name{i});

        if ~strcmp(sourceBase, targetBase)
            validSources(end+1) = i;
        end
    end

    if numel(unique(validSources)) >= 2
        branchNodes(end+1) = j;
    end
end

